if(b.dataset.sendDraft){const f=$('#mail-draft-form');if(f?.dataset.dirty==='true')throw Error('Enregistrez vos modifications et relisez l’aperçu avant l’envoi.');if(confirm('Envoyer ce message à '+b.dataset.recipient+' ?')){b.disabled=true;try{const r=await api('action',{action:'mail-send',id:b.dataset.sendDraft,version:Number(b.dataset.version)});await load();await openEvent(opened);toast(r.status==='sent'?'Message envoyé.':'Message enregistré pour envoi. Le système réessaiera si nécessaire.');}finally{b.disabled=false;}}}
if(b.dataset.month){const n=Number(b.dataset.month),d=n?new Date(year,month+n,1):new Date();year=d.getFullYear();month=d.getMonth();render();}
if(b.dataset.supplier)supplierForm(b.dataset.supplier);
