if(b.dataset.command==='new-prospect')prospectForm();
if(b.dataset.newNote)noteForm('',b.dataset.newNote);
if(b.dataset.deleteTask&&confirm('Supprimer cette tâche ?')){const r=await api('action',{action:'task-delete',id:b.dataset.deleteTask});await load();await openEvent(r.id);}
if(b.dataset.briefDelete){const r=await api('action',{action:'brief-item',id:b.dataset.briefDelete,delete:true});await load();await openEvent(r.id);}
if(b.dataset.briefOpen)await openBrief(b.dataset.briefOpen);
if(b.dataset.newChecklist)checklistForm('',b.dataset.newChecklist);
